    author: "adamgiebl",
    html: "<button class=\"game-button\">\n    <svg class=\"play-icon\" viewBox=\"0 0 40 40\">\n        <path d=\"M 10,10 L 30,20 L 10,30 z\"></path>\n    </svg>\n    Play Now\n</button>",
    css: "/* From Uiverse.io by adamgiebl - Tags: button */\n.game-button {\n  background-color: #ff7979;\n  color: #fff;\n  border: none;\n  border-radius: 20px;\n  padding: 10px 20px;\n  font-size: 18px;\n  text-transform: uppercase;\n  letter-spacing: 2px;\n  font-weight: bold;\n  box-shadow: 2px 2px 10px #ff7979;\n  transition: all 0.2s ease-in-out;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  position: relative;\n}\n\n.play-icon {\n  width: 24px;\n  height: 24px;\n  fill: #fff;\n  margin-right: 10px;\n}\n\n.game-button:hover {\n  background-color: #2f3640;\n  color: #ff7979;\n  box-shadow: 2px 2px 20px #2f3640;\n  transform: translateY(-2px);\n}",
