    css: "/* From Uiverse.io by meermubashar - Tags: button */\nbutton {\n width: 140px;\n height: 45px;\n font-size: 23px;\n cursor: pointer;\n border: none;\n outline: none;\n background: transparent;\n color: white;\n font-family: 'Times New Roman', Times, serif;\n font-weight: 700;\n position: relative;\n transition: all 0.5s;\n z-index: 1;\n}\n\nbutton::before {\n content: \"\";\n position: absolute;\n top: 0;\n left: 0;\n width: 5px;\n height: 100%;\n background-color: white;\n z-index: -1;\n transition: all 0.5s;\n}\n\nbutton:hover::before {\n width: 100%;\n}\n\nbutton:hover {\n color: black;\n}\n\nbutton:active:before {\n background: #b9b9b9;\n}",
