    css: "/* From Uiverse.io by codebykay101  - Tags: simple, card, neon, cool card, cardhover , card animation, card hover */\n.container {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 20px;\n}\n\n.loader {\n  position: relative;\n  width: 150px;\n  height: 150px;\n  background: rgba(45, 45, 45, 1);\n  overflow: hidden;\n  transform: rotate(calc(90deg * var(--i)));\n}\n\n.loader::before {\n  content: \"\";\n  position: absolute;\n  width: 300px;\n  height: 300px;\n  background: radial-gradient(var(--clr), transparent);\n  animation: animate 1.5s linear infinite;\n}\n\n.loader::after {\n  content: \"\";\n  position: absolute;\n  inset: 2px;\n  background: rgba(45, 45, 45, 0.9);\n}\n\n@keyframes animate {\n  0% {\n    transform: translate(-150px, -150px);\n  }\n  25% {\n    transform: translate(0px, -150px);\n  }\n  50% {\n    transform: translate(0px, 0px);\n  }\n  75% {\n    transform: translate(-150px, 0px);\n  }\n  100% {\n    transform: translate(-150px, -150px);\n  }\n}",
