    css: "/* From Uiverse.io by gharsh11032000  - Tags: card, hover, hover effect, hoverme, cardhover , card hover */\n.card {\n  width: 320px;\n  height: 350px;\n  padding: 20px;\n  color: white;\n  background: transparent;\n  border: 2px solid #ff6b00;\n  display: flex;\n  flex-direction: column;\n  cursor: pointer;\n  transform-origin: center center;\n  transition: all 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n}\n\n.card .main-content {\n  flex: 1;\n}\n\n.header {\n  margin-bottom: 24px;\n}\n\n.card .heading {\n  font-size: 32px;\n  font-weight: 400;\n  line-height: 1.2;\n}\n\n.card .footer {\n  font-weight: 400;\n  margin-right: 4px;\n}\n\n.card:hover {\n  border-radius: 12px;\n  background-color: #ff6b00;\n  scale: 0.95;\n  rotate: 8deg;\n  box-shadow: 0px 3px 187.5px 7.5px rgba(255, 107, 0, 0.4);\n}",
