    title: "Rude Dingo",
    author: "reshades",
    html: "<div class=\"card\">\n  <div class=\"top\">\n    <p class=\"title\">script.py</p>\n    <span class=\"buttons\">\n    <button class=\"minimize\">\n\t\t\t<svg viewBox=\"0 0 10.2 1\" y=\"0px\" x=\"0px\"><rect height=\"1\" width=\"10.2\" y=\"50%\" x=\"0\"></rect></svg>\n\t\t</button>\n    <button class=\"maximize\">\n\t\t\t<svg viewBox=\"0 0 10 10\"><path d=\"M0,0v10h10V0H0z M9,9H1V1h8V9z\"></path></svg>\n\t\t</button>\n    <button class=\"close\">\n\t\t\t<svg viewBox=\"0 0 10 10\"><polygon points=\"10.2,0.7 9.5,0 5.1,4.4 0.7,0 0,0.7 4.4,5.1 0,9.5 0.7,10.2 5.1,5.8 9.5,10.2 10.2,9.5 5.8,5.1\"></polygon></svg>\n\t\t</button>\n    </span>\n\n  </div>\n  <div class=\"topfix\">\n  </div>\n<hr>\n  <div class=\"content\">\n    <p>\n      <code>\n        <i class=\"c1\">import</i> os, sys<br>\n        <b class=\"c2\">os</b>.system<b class=\"c3\">(</b><b class=\"c4\">\"title test script\"</b><b class=\"c3\">)</b><br>\n        <b class=\"c2\">print</b><b class=\"c3\">(</b><b class=\"c4\">\"Hello UIVERSE.io!\"</b><b class=\"c3\">)</b><br>\n        <b class=\"c2\">sys</b>.exit<b class=\"c3\">(</b><b class=\"c3\">)</b><br>\n        <i class=\"comment\">#this is a comment.</i>\n      </code>\n    </p>\n  </div>\n</div>",
    css: "/* From Uiverse.io by reshades - Tags: card, editor, code, vscode */\n.card {\n  width: 250px;\n  height: 254px;\n  background: #121212;\n  border-radius: 10px;\n  border: 1px #212121 solid;\n}\n\n.card hr {\n  color: #313131;\n  margin-top: -3.5px\n}\n\n.content {\n  color: #8e8e8e;\n  margin-left: 0.3em;\n}\n\n.c1 {\n  color: rgb(55, 91, 158)\n}\n\n.c2 {\n  color: rgb(55, 158, 150)\n}\n\n.c3 {\n  color: rgb(158, 151, 55)\n}\n\n.c4 {\n  color: rgb(88, 158, 55)\n}\n\n.comment {\n  opacity: 50%\n}\n\n.title {\n  color: #e8e8e8;\n  font-size: small;\n  float: left;\n  margin-left: 0.6em;\n  margin-top: 0.6em;\n}\n\n.top {\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  font-size: 21px;\n  font-weight: 450;\n  background-color: #121212;\n  width: 100%;\n  text-align: right;\n  border-radius: 10px\n}\n\n.topfix {\n  background-color: #121212;\n  width: 100%;\n  height: 1em;\n  margin-top: -1em;\n}\n\nbutton {\n  width: 40px;\n  height: 35px;\n  margin-left: -5px;\n  border: 0;\n  outline: 0;\n  background: transparent;\n  transition: 0.2s;\n}\n\nbutton svg path, \nbutton svg rect, \nbutton svg polygon {\n  fill: #ffffff;\n}\n\nbutton svg {\n  width: 10px;\n  height: 10px;\n}\n\n.close:hover {\n  background-color: #ffffff10;\n}\n\n.maximize:hover {\n  background-color: #ffffff10;\n}\n\n.minimize:hover {\n  background-color: #ffffff10;\n}",
