    author: "JulioCodesSM",
    html: "<label for=\"toggle\" class=\"button\">\n  <input type=\"checkbox\" id=\"toggle\">\n  <span class=\"slider\"></span>\n</label>",
    css: "/* From Uiverse.io by JulioCodesSM - Tags: switch */\n.button {\n  display: inline-block;\n  width: 50px;\n  height: 20px;\n  background-color: #fff;\n  border-radius: 30px;\n  cursor: pointer;\n  padding: 0;\n  color: white;\n}\n\n#toggle {\n  display: none;\n}\n\n.slider {\n  display: block;\n  font-size: 10px;\n  position: relative;\n}\n\n.slider::after {\n  content: 'OFF';\n  width: 25px;\n  height: 25px;\n  background-color: #e03c3c;\n  border: 2px solid #fff;\n  border-radius: 50%;\n  box-shadow: 0 0 5px rgba(0, 0, 0, .25);\n  position: absolute;\n  top: -5px;\n  left: 0;\n  display: grid;\n  place-content: center;\n  line-height: 0;\n  transition: background-color .25s, transform .25s ease-in;\n}\n\n#toggle:checked + .slider::after {\n  content: 'ON';\n  background-color: #05ae3e;\n  transform: translateX(25px) rotate(360deg);\n}",
